#pragma once
// Anti-aliased bitmap fonts: 4-bit coverage, tight per-glyph bounding boxes,
// a sorted code-point table (so subsets such as clock digits stay small).
// Generated by tools/fontgen.py; see src/stella/fonts/fonts.h.
#include <stdint.h>

namespace stella {

struct Glyph {
  uint32_t offset;  // into Font::bitmap, in bytes; rows are packed, 2 px/byte, high nibble first
  uint8_t width, height;
  int8_t left;      // pen x to the bitmap's left edge
  int8_t top;       // baseline to the bitmap's top edge (positive = above baseline)
  uint8_t advance;  // pen advance in pixels
};

struct Font {
  const char *name;
  const uint8_t *bitmap;
  const Glyph *glyphs;
  const uint16_t *codepoints;  // ascending, parallel to glyphs
  uint16_t count;
  uint16_t fallback;  // glyph index used for unsupported characters
  uint8_t ascent, descent, lineHeight;

  // Glyph index for a code point, or `fallback`.
  uint16_t find(uint32_t cp) const {
    if (cp >= 32 && cp - 32 < count && codepoints[cp - 32] == cp) return (uint16_t)(cp - 32);  // ASCII fast path
    uint16_t lo = 0, hi = count;
    while (lo < hi) {
      const uint16_t mid = (uint16_t)((lo + hi) / 2);
      if (codepoints[mid] < cp) lo = (uint16_t)(mid + 1);
      else hi = mid;
    }
    return (lo < count && codepoints[lo] == cp) ? lo : fallback;
  }
};

}  // namespace stella
